56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        if (normalizedTelephone == null) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
112	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.CONFLICT);
117	        }
118	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (countOwnersRegisteredOn(LocalDate.now()) >= 100) {
122	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
123	        }
124	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
125	        List<Owner> householdMembers =
126	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
127	        if (!sharesHousehold && !householdMembers.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setTelephone(normalizedTelephone);
133	        if (owner.getRegistrationDate() == null) {
134	            owner.setRegistrationDate(LocalDate.now());
135	        }
136	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
137	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
138	        if (sharesHousehold && !householdMembers.isEmpty()) {
139	            String householdId = householdId(owner.getLastName(), normalizedAddress);
140	            owner.setHouseholdId(householdId);
141	            for (Owner member : householdMembers) {
142	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
143	                    member.setHouseholdId(householdId);
144	                    this.clinicService.saveOwner(member);
145	                }
146	            }
147	        }
148	        this.clinicService.saveOwner(owner);
149	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
158	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
159	        if (currentOwner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
163	        if (normalizedTelephone == null) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(normalizedTelephone);
171	        currentOwner.setEmail(ownerFieldsDto.getEmail());
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
