207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    /**
241	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
242	     * stripped. When a leading {@code '+'} and country code are present they are kept;
243	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
244	     * is dropped from the national digits. The result must be a {@code '+'} followed
245	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
246	     * is returned to signal a bad request.
247	     */
248	    /**
249	     * Build the customer code for a newly created owner, formatted
250	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
251	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
252	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
253	     * one more than the number of owners already in that city.
254	     */
255	    private String nextCustomerCode(String city, String lastName) {
256	        String cityPrefix = prefixThree(city);
257	        String lastNamePrefix = prefixThree(lastName);
258	        String normalizedCity = normalizeForHousehold(city);
259	        int sequence = (int) this.clinicService.findAllOwners().stream()
260	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
261	            .count() + 1;
262	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
263	    }
264	
265	    /**
266	     * Count the existing owners whose city matches the given one, compared after
267	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
268	     * cap: a city that already holds this many owners is at capacity.
269	     */
270	    private long countOwnersInCity(String city) {
271	        String normalizedCity = normalizeForHousehold(city);
272	        return this.clinicService.findAllOwners().stream()
273	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
274	            .count();
275	    }
276	
277	    /**
278	     * Count the existing owners whose registration date falls on the given day. Used to
279	     * enforce the per-day create limit: once this many owners have been registered today,
280	     * the day is at capacity and further creates are rejected.
281	     */
282	    private long countOwnersRegisteredOn(LocalDate day) {
283	        return this.clinicService.findAllOwners().stream()
284	            .filter(existing -> day.equals(existing.getRegistrationDate()))
285	            .count();
286	    }
287	
288	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
289	    private String prefixThree(String value) {
290	        String v = value == null ? "" : value;
291	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
292	    }
293	
294	    /**
295	     * Find the existing owners that already belong to the same household as the given
296	     * last name and address, i.e. those sharing both fields. Both are compared
297	     * case-insensitively after collapsing runs of whitespace to a single space and
298	     * trimming the ends.
299	     */
300	    private List<Owner> findHouseholdMembers(String lastName, String address) {
301	        String normalizedLastName = normalizeForHousehold(lastName);
302	        String normalizedAddress = normalizeForHousehold(address);
303	        return this.clinicService.findAllOwners().stream()
304	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
305	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
306	            .toList();
307	    }
308	
309	    /**
310	     * Count the existing owners that already share both the given first and last
311	     * name, compared case-insensitively. Used to populate an owner's namesake count
312	     * at creation time, reflecting how many owners with the same name existed before
313	     * this one was created.
314	     */
315	    private int countNamesakes(String firstName, String lastName) {
316	        String normalizedFirstName = normalizeName(firstName);
317	        String normalizedLastName = normalizeName(lastName);
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
320	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
321	            .count();
322	    }
323	
324	    private String normalizeName(String value) {
325	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
326	    }
327	
328	    /**
329	     * Build a stable identifier shared by all owners of one household. It is derived
330	     * deterministically from the normalized last name and address, so every owner at
331	     * the same household resolves to the same value regardless of creation order.
332	     */
333	    private String householdId(String lastName, String address) {
334	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
335	        try {
336	            byte[] digest = MessageDigest.getInstance("SHA-256")
337	                .digest(key.getBytes(StandardCharsets.UTF_8));
338	            StringBuilder sb = new StringBuilder();
339	            for (int i = 0; i < 6; i++) {
340	                sb.append(String.format("%02X", digest[i]));
341	            }
342	            return "HH-" + sb;
343	        }
344	        catch (NoSuchAlgorithmException e) {
345	            throw new IllegalStateException(e);
346	        }
347	    }
348	
349	    private String normalizeForHousehold(String value) {
350	        if (value == null) {
351	            return "";
352	        }
353	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
354	    }
355	
356	    private String normalizeTelephone(String telephone) {
357	        if (telephone == null) {
358	            return null;
359	        }
360	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
361	        String digits;
362	        if (cleaned.startsWith("+")) {
363	            digits = cleaned.substring(1);
364	        } else {
365	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
366	            digits = "61" + national;
367	        }
368	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
374	        Owner owner = this.clinicService.findOwnerById(ownerId);
375	        if (owner != null) {
376	            Pet pet = owner.getPet(petId);
377	            if (pet != null) {
378	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
379	            }
380	        }
381	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	    }
383	}
